CREATE OR REPLACE FUNCTION public.estrategia_revisar_sugestoes(_itens jsonb,_acao text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item jsonb; s public.estrategia_sugestoes%ROWTYPE; t text; r uuid; n integer:=0; BEGIN IF NOT coalesce(public.proj_gov_ou_ceo(auth.uid()),false) THEN RAISE EXCEPTION 'Apenas Governança e CEO.'; END IF; IF _acao IS NULL OR _acao NOT IN('aprovar','rejeitar') OR _itens IS NULL OR jsonb_typeof(_itens)<>'array' OR jsonb_array_length(_itens) NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'Seleção inválida (1–1000).'; END IF; FOR item IN SELECT value FROM jsonb_array_elements(_itens) ORDER BY value->>'id' LOOP SELECT * INTO s FROM public.estrategia_sugestoes WHERE id=(item->>'id')::uuid FOR UPDATE; IF NOT FOUND OR s.status<>'pendente' OR NOT public.estrategia_fonte_visivel(s.origem_tipo,s.origem_id) THEN RAISE EXCEPTION 'Sugestão indisponível ou já revisada.'; END IF; t:=coalesce(item->>'tipo',s.tipo); r:=coalesce((item->>'ref_id')::uuid,s.ref_id); IF _acao='aprovar' THEN IF NOT public.estrategia_alvo_ativo(t,r) THEN RAISE EXCEPTION 'O item selecionado não está vigente.'; END IF; INSERT INTO public.estrategia_vinculos_gov(origem_tipo,origem_id,tipo,ref_id,criado_por) VALUES(s.origem_tipo,s.origem_id,t,r,auth.uid()) ON CONFLICT(origem_tipo,origem_id,tipo,ref_id) DO NOTHING; END IF; UPDATE public.estrategia_sugestoes SET status=CASE WHEN _acao='aprovar' THEN 'aprovada' ELSE 'rejeitada' END,revisado_por=auth.uid(),revisado_em=now(),aprovado_tipo=CASE WHEN _acao='aprovar' THEN t END,aprovado_ref_id=CASE WHEN _acao='aprovar' THEN r END WHERE id=s.id; INSERT INTO public.estrategia_sugestoes_auditoria(sugestao_id,acao,usuario_id,tipo,ref_id) VALUES(s.id,_acao,auth.uid(),t,r); n:=n+1; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.estrategia_revisar_sugestoes(jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.estrategia_revisar_sugestoes(jsonb,text) TO authenticated;